  2375	                cunpsz = 4;
  2376	            cunpsz *= (uint64_t) compute_sampled_width (w, xsamp, dw.min.x);
  2377	            cunpsz *= (uint64_t) compute_sampled_height (linePerChunk, ysamp, dw.min.y);
  2378	            if (ysamp > 1)
  2379	                hasLineSample = 1;
  2380	            unpackedsize += cunpsz;
  2381	        }
  2382	
  2383	        curpart->unpacked_size_per_chunk = unpackedsize;
  2384	        curpart->chan_has_line_sampling  = ((int16_t) hasLineSample);
  2385	
  2386	        h      = (uint64_t) ((int64_t) dw.max.y - (int64_t) dw.min.y + 1);
  2387	        retval = (int32_t) ((h + linePerChunk - 1) / linePerChunk);
  2388	    }
  2389	    return retval;
  2390	}
