  2525	/**************************************/
  2526	
  2527	exr_result_t
  2528	internal_exr_check_magic (exr_context_t ctxt)
  2529	{
  2530	    uint32_t     flags;
  2531	    uint64_t     initpos;
  2532	    exr_result_t rv = EXR_ERR_UNKNOWN;
  2533	
  2534	    rv = read_magic_and_flags (ctxt, &flags, &initpos);
  2535	    return rv;
  2536	}
